// appendTo appends the entry's fields to dst in the order of l, the entry's
// layout in the message being built. Fields and nested groups l does not list
// are not written: that message's readers could not find them, nor the entries
// after them.
func (e *NoQuoteEntriesEntryBuilder) appendTo(dst []fix.Field, l *groupLayout) []fix.Field {
	for _, tag := range l.tags {
		switch tag {
		case TagNoContractualDefinitions:
			if len(e.noContractualDefinitionsEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoContractualDefinitions, len(e.noContractualDefinitionsEntries))
				for _, entry := range e.noContractualDefinitionsEntries {
					dst = entry.appendTo(dst, l.nested[TagNoContractualDefinitions])
				}
			}
		case TagNoContractualMatrices:
			if len(e.noContractualMatricesEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoContractualMatrices, len(e.noContractualMatricesEntries))
				for _, entry := range e.noContractualMatricesEntries {
					dst = entry.appendTo(dst, l.nested[TagNoContractualMatrices])
				}
			}
		case TagNoEvents:
			if len(e.noEventsEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoEvents, len(e.noEventsEntries))
				for _, entry := range e.noEventsEntries {
					dst = entry.appendTo(dst, l.nested[TagNoEvents])
				}
			}
		case TagNoFinancingTermSupplements:
			if len(e.noFinancingTermSupplementsEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoFinancingTermSupplements, len(e.noFinancingTermSupplementsEntries))
				for _, entry := range e.noFinancingTermSupplementsEntries {
					dst = entry.appendTo(dst, l.nested[TagNoFinancingTermSupplements])
				}
			}
		case TagNoInstrumentParties:
			if len(e.noInstrumentPartiesEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoInstrumentParties, len(e.noInstrumentPartiesEntries))
				for _, entry := range e.noInstrumentPartiesEntries {
					dst = entry.appendTo(dst, l.nested[TagNoInstrumentParties])
				}
			}
		case TagNoSecurityAltID:
			if len(e.noSecurityAltIDEntries) > 0 || tag == l.tags[0] {
				dst = fix.AppendCount(dst, TagNoSecurityAltID, len(e.noSecurityAltIDEntries))
				for _, entry := range e.noSecurityAltIDEntries {
					dst = entry.appendTo(dst, l.nested[TagNoSecurityAltID])
				}
			}
		default:
			dst = fix.AppendField(dst, e.fields, tag)
		}
	}
	return dst
}
